    [
      ".....B",
      "......",
      "......",
      ".WWW..",
      ".WWW..",
      ".WWW..",
      "KK....",
    ].map((r, i) => (i === 1 ? "......" : r)),
    // y5: pot on the barrel, water basin and a pot on the washstand
    [
      ".....F",
      "......",
      "......",
      "......",
      "......",
      "......",
      "CF....",
    ],
    // y6: mirror panes on the wall behind the basin
    [
      "......",
      "......",
      "......",
      "......",
      "......",
      "......",
      "GG....",
    ],
    // y7: mirror, second course
    [
      "......",
      "......",
      "......",
      "......",
      "......",
      "......",
      "GG....",
    ],
    // y8: iron bar cornice over the mirror
    [
      "......",
      "......",
      "......",
      "......",
      "......",
      "......",
      "II....",
    ],
    // y9: hanging lantern over the rug (under the upper floor at y10)
    [
      "......",
      "......",
      "..L...",
      "......",
      "......",
      "......",
      "......",
    ],
  ]);
  // the chair at (64,4,59), facing the washstand (south)
  // (drawn by the stairs legend above only where a row carries 'S'; see the y4 rows: the chair sits on z59)
}

